#!/usr/bin/env python3
from PIL import Image
import sys
import numpy as np

def display_image_as_text(image_path):
    try:
        img = Image.open(image_path)
        print(f"Image size: {img.width}x{img.height}")
        print(f"Image mode: {img.mode}")

        # Convert to RGB if needed
        if img.mode != 'RGB':
            img = img.convert('RGB')

        # Resize for better terminal display
        height = 120  # Adjust based on your terminal
        ratio = height / img.height
        width = int(img.width * ratio)
        img = img.resize((width, height))

        # Convert to numpy array
        pixels = np.array(img)

        # Display as ASCII art
        for y in range(img.height):
            line = ""
            for x in range(img.width):
                pixel = pixels[y, x]
                # For RGB images
                if isinstance(pixel, np.ndarray):
                    # Calculate brightness
                    brightness = sum(pixel) / (3 * 255)
                else:
                    # For grayscale
                    brightness = pixel / 255

                # Choose character based on brightness
                # Reverse the scale so dark pixels are represented with '@' (more visible)
                if brightness > 0.8:
                    char = " "
                elif brightness > 0.6:
                    char = "."
                elif brightness > 0.4:
                    char = "+"
                elif brightness > 0.2:
                    char = "@"
                else:
                    char = "@"

                line += char + char  # Double the char for better aspect ratio
            print(line)

    except Exception as e:
        print(f"Error displaying image: {e}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python3 display_image.py <image_path>")
        sys.exit(1)

    display_image_as_text(sys.argv[1])
